//! Protobuf types of the Celaut node `Gateway`.
//!
//! The `.proto` files in `protos/` are copied from
//! [celaut-project/nodo](https://github.com/celaut-project/nodo) (`protos/`). The
//! commit is in `protos/SOURCE`. The Rust code in `src/gen/` is generated by
//! `cargo run -p gen-protos` and committed.

#![allow(clippy::all, missing_docs)]

pub mod buffer {
    include!("gen/buffer.rs");
}

pub mod celaut {
    include!("gen/celaut.rs");
}

/// The peer invitation of a QR code (`invite.proto`, nodo#579).
pub mod invite {
    include!("gen/invite.rs");
}

pub use prost::Message;
